const tokyoEvents=[{"id":"sakura","name":"벚꽃 산책","type":"계절","area":"도쿄 전역","months":[3,4],"timing":"예년 3월 하순~4월 초","scheduleType":"해마다 변동","description":"우에노·지도리가후치·이노카시라가 대표적입니다. 품종과 기온에 따라 차이가 있고, 신주쿠교엔에서는 여러 품종을 만날 수 있습니다.","source":"https://www.gotokyo.org/en/story/guide/spring/index.html"},{"id":"autumn","name":"도심 단풍·은행나무","type":"계절","area":"도쿄 전역","months":[11,12],"timing":"예년 11월~12월 초","scheduleType":"해마다 변동","description":"도심의 단풍은 늦가을에 즐깁니다. 정원과 은행나무길을 골라보세요. 산간과 도심은 절정 시기가 같지 않으며 날씨에 따라 달라집니다.","source":"https://www.gotokyo.org/en/story/guide/autumn/index.html"},{"id":"sanja","name":"산자마쓰리","type":"마쓰리","area":"아사쿠사·스미다","months":[5],"timing":"예년 5월 중순, 3일간","scheduleType":"매년 일정 발표","description":"아사쿠사에서 미코시 행렬과 마을 축제 분위기를 만납니다. 2026년 일정은 5월 15~17일로 이미 종료되었습니다. 다음 회차 날짜는 주최 측 공지를 확인하세요.","source":"https://asakusajinja.jp/sanjamatsuri/schedule/"},{"id":"kanda","name":"간다마쓰리","type":"마쓰리","area":"간다·아키하바라","months":[5],"timing":"5월 무렵 · 본마쓰리 홀수 해","scheduleType":"격년 행사","description":"간다 일대의 대표 축제입니다. 큰 행렬이 열리는 본마쓰리와 짝수 해의 제례를 구분해야 합니다. 다음 본마쓰리의 구체적 날짜는 공식 발표를 확인하세요.","source":"https://www.gotokyo.org/en/story/guide/may/index.html"},{"id":"sanno","name":"산노마쓰리","type":"마쓰리","area":"아카사카","months":[6],"timing":"예년 6월 중순","scheduleType":"대행렬 격년","description":"히에 신사 중심의 축제입니다. 도심을 지나는 큰 행렬은 매년 열리는 것이 아니므로 방문 연도의 행렬 개최 여부와 날짜를 확인하세요.","source":"https://www.tenkamatsuri.jp/"},{"id":"sumida","name":"스미다가와 불꽃놀이","type":"불꽃놀이","area":"아사쿠사·스미다","months":[7],"timing":"예년 7월 하순","scheduleType":"매년 일정 발표","description":"스미다강의 대표적인 대형 불꽃놀이입니다. 2026년 7월 25일 행사는 종료되었습니다. 혼잡과 통행 제한이 있어 관람구역을 미리 확인하세요.","source":"https://www.sumidagawa-hanabi.com/"},{"id":"edogawa","name":"에도가와구 불꽃놀이","type":"불꽃놀이","area":"에도가와","months":[8],"timing":"최근 8월 초 개최","scheduleType":"매년 일정 발표","description":"에도가와 강변에서 열리는 대형 불꽃놀이입니다. 2026년 8월 1일 행사는 종료되었습니다. 강 건너 관람구역과 도쿄 쪽 접근 경로를 구분하세요.","source":"https://www.city.edogawa.tokyo.jp/hanabi/"},{"id":"awa","name":"도쿄 고엔지 아와오도리","type":"마쓰리","area":"기치조지·고엔지","months":[8],"timing":"예년 8월 하순 주말","scheduleType":"매년 일정 발표","description":"고엔지 역 주변 거리에서 춤과 음악을 즐기는 축제입니다. 2026년 8월 29~30일 행사는 종료되었습니다. 관람 동선·통제를 사전에 확인하세요.","source":"https://www.koenji-awaodori.com/about/about01.html"},{"id":"hozuki","name":"센소지 꽈리 시장","type":"시장·제례","area":"아사쿠사·스미다","months":[7],"timing":"매년 7월 9~10일","scheduleType":"고정 날짜","description":"센소지의 사만육천일 제례와 함께 꽈리 화분을 파는 시장이 열립니다. 한여름의 전통 시장 분위기를 즐겨보세요.","source":"https://www.senso-ji.jp/annual_event/13.html"},{"id":"hagoita","name":"센소지 하고이타 시장","type":"시장·제례","area":"아사쿠사·스미다","months":[12],"timing":"매년 12월 17~19일","scheduleType":"고정 날짜","description":"연말에 장식용 하고이타를 구경하는 전통 시장입니다. 길운을 기원하는 화려한 장식과 장인의 작품을 만나보세요.","source":"https://www.senso-ji.jp/annual_event/21.html"},{"id":"bunkyo-ume","name":"분쿄 매화축제","type":"꽃축제","area":"우에노·야나카","months":[2,3],"timing":"예년 2월 초~3월 초","scheduleType":"매년 일정 발표","description":"유시마텐만구의 약 300그루 매화가 피는 시기에 열리는 봄맞이 행사입니다. 개화 상황과 행사 기간은 방문 연도 공식 안내를 확인하세요.","source":"https://www.gotokyo.org/en/spot/ev149/index.html"},{"id":"bunkyo-azalea","name":"분쿄 철쭉축제","type":"꽃축제","area":"우에노·야나카","months":[4],"timing":"예년 4월","scheduleType":"매년 일정 발표","description":"네즈 신사의 넓은 철쭉 정원에서 다양한 품종의 꽃을 만날 수 있는 봄 행사입니다. 개화 상황에 따라 관람 조건이 달라질 수 있습니다.","source":"https://www.gotokyo.org/en/spot/ev186/index.html"},{"id":"kameido-wisteria","name":"가메이도텐진 등나무축제","type":"꽃축제","area":"료고쿠·스미다","months":[4],"timing":"예년 4월","scheduleType":"매년 일정 발표","description":"가메이도텐진의 연못 위 등나무 시렁이 보랏빛으로 물드는 봄 행사입니다. 개화 시기는 기온에 따라 달라지므로 방문 전 상태를 확인하세요.","source":"https://www.gotokyo.org/en/spot/ev197/index.html"},{"id":"bunkyo-ajisai","name":"분쿄 수국축제","type":"꽃축제","area":"고쿄·분쿄","months":[6],"timing":"예년 6월 초~중순","scheduleType":"매년 일정 발표","description":"하쿠산 신사와 하쿠산 공원 주변에 수천 그루의 수국이 피는 초여름 행사입니다. 주말에는 행사와 판매 부스가 추가될 수 있습니다.","source":"https://www.gotokyo.org/en/spot/ev031/index.html"},{"id":"marunouchi-illumination","name":"마루노우치 일루미네이션","type":"일루미네이션","area":"도쿄역·긴자·쓰키지","months":[11,12,1,2],"timing":"예년 11월~2월","scheduleType":"매년 일정 발표","description":"도쿄역 앞과 마루노우치 나카도리를 중심으로 샴페인 골드빛 조명이 이어지는 겨울 행사입니다. 해당 연도의 점등 기간과 시간은 공식 안내를 확인하세요.","source":"https://www.gotokyo.org/en/spot/ev002/index.html"}];
